    11	    std::complex<Real> heston_log_return_characteristic_function(
    12	        Real u, Real ttm, const HestonParams &p) noexcept
    13	    {
    14	        using C = std::complex<Real>;
    15	        constexpr C i(0.0, 1.0);
    16	
    17	        const C beta = p.kappa - i * p.rho * p.xi * u; // shorthand, appears repeatedly below
    18	        const C d_squared_minus_beta_squared = p.xi * p.xi * C(u * u, u);
    19	        const C D = std::sqrt(beta * beta + d_squared_minus_beta_squared);
    20	        const C beta_plus_D = beta + D;
    21	
    22	        // beta - D is computed via beta^2 - D^2 = -d_squared_minus_beta_squared
    23	        // rather than as a direct subtraction: for small xi, beta and D are
    24	        // both within O(xi^2) of each other (D -> beta as xi -> 0), so a
    25	        // direct subtraction loses precision catastrophically once xi drops
    26	        // much below 1e-3 -- verified empirically (tests/testHestonCOS.cpp
    27	        // hit prices off by 5+ orders of magnitude before this fix). This
    28	        // form is a division of two well-scaled quantities instead, with no
    29	        // cancellation.
    30	        const C beta_minus_D = -d_squared_minus_beta_squared / beta_plus_D;
    31	        const C G = beta_minus_D / beta_plus_D;
    32	
    33	        const C exp_mDt = std::exp(-D * ttm);
    34	        const C term_v0 = (p.v0 / (p.xi * p.xi)) * beta_minus_D * (Real(1.0) - exp_mDt) / (Real(1.0) - G * exp_mDt);
